class Solution { struct DSU{vector<int> parent,rank;DSU(int n):parent(n+1),rank(n+1){iota(parent.begin(),parent.end(),0);}int find(int x){return parent[x]==x?x:parent[x]=find(parent[x]);}void unite(int a,int b){a=find(a);b=find(b);if(a==b)return;if(rank[a]<rank[b])swap(a,b);parent[b]=a;if(rank[a]==rank[b])++rank[a];}};public:vector<bool> areConnected(int n,int threshold,vector<vector<int>>& queries){DSU dsu(n);for(int factor=threshold+1;factor<=n;++factor)for(int multiple=factor*2;multiple<=n;multiple+=factor)dsu.unite(factor,multiple);vector<bool> answer;for(auto& query:queries)answer.push_back(dsu.find(query[0])==dsu.find(query[1]));return answer;} };
